//! # Reference corpus: the EC-Index-Calculus-Benchmarks instances.
//!
//! Sixty binary-Semaev `S₄` decomposition problems, independently
//! generated by [`mtrimoska/EC-Index-Calculus-Benchmarks`][up], carried
//! here as a regression corpus for
//! [`crate::cryptanalysis::semaev_sat`].
//!
//! [up]: https://github.com/mtrimoska/EC-Index-Calculus-Benchmarks
//!
//! ## What is and is not vendored
//!
//! Only the **parameters** of each instance: the field, the target
//! x-coordinate, and the decomposition the generator planted.  The
//! generated DIMACS and ANF files themselves are not copied — upstream
//! is GPL-3.0 and this crate carries no licence declaration, so
//! importing its output would be a licensing decision rather than an
//! engineering one.  Regenerating each instance from its parameters
//! with our own encoder is also the better test: it exercises the whole
//! pipeline instead of replaying someone else's output.
//!
//! ## Labels are expectations, not certificates
//!
//! Upstream names each instance `-S` or `-U`.  The `-S` instances are
//! built by *constructing* a decomposition, so a solution provably
//! exists.  The `-U` instances are built from a **random** target
//! x-coordinate, which is merely unlikely to decompose — the label is
//! the expected outcome, not a proof.
//!
//! Deciding all thirty `-U` instances exhaustively shows the
//! distinction is not academic: **`n19l6-19-U` is satisfiable.**  So
//! this table records `labelled_sat` (what the filename claims) and
//! `truly_sat` (what exhaustive search establishes) separately, and
//! `tests::corpus_labels_match_exhaustive_search` re-derives the
//! latter rather than trusting it.
//!
//! See `research/notes/ecc2k130/RESEARCH_TRIMOSKA_BENCHMARKS.md` for the full review.

use crate::binary_ecc::{F2mElement, IrreduciblePoly};
use crate::cryptanalysis::binary_semaev_s4::{elementary_symmetric_3, symmetrised_s4_eval};

/// One decomposition problem: given `x_r`, are there three factor-base
/// x-coordinates whose symmetrised `S₄` vanishes?
#[derive(Debug, Clone)]
pub struct CorpusInstance {
    /// Upstream filename stem, e.g. `n19l6-19-U`.
    pub name: &'static str,
    /// Extension degree of the field.
    pub n: u32,
    /// Dimension of the factor-base subspace `⟨1, z, …, z^{l−1}⟩`.
    pub l: u32,
    /// Non-leading exponents of the irreducible polynomial.
    pub irr_low_terms: &'static [u32],
    /// Set bit positions of the target x-coordinate.
    pub x_r_bits: &'static [u32],
    /// The decomposition upstream planted, as set bit positions of
    /// `X₁, X₂, X₃`.  Present exactly for the `-S` instances.
    pub planted: Option<[&'static [u32]; 3]>,
    /// What the upstream filename claims.
    pub labelled_sat: bool,
    /// What exhaustive search over the factor base establishes.  Equal
    /// to `labelled_sat` everywhere except `n19l6-19-U`.
    pub truly_sat: bool,
}

impl CorpusInstance {
    pub fn irr(&self) -> IrreduciblePoly {
        IrreduciblePoly {
            degree: self.n,
            low_terms: self.irr_low_terms.to_vec(),
        }
    }

    pub fn x_r(&self) -> F2mElement {
        F2mElement::from_bit_positions(self.x_r_bits, self.n)
    }

    /// The curve constant: every instance is on the Koblitz curve
    /// `y² + xy = x³ + x² + 1`.
    pub fn b(&self) -> F2mElement {
        F2mElement::one(self.n)
    }

    /// The planted decomposition as field elements, if there is one.
    pub fn planted_elements(&self) -> Option<[F2mElement; 3]> {
        self.planted
            .map(|p| std::array::from_fn(|i| F2mElement::from_bit_positions(p[i], self.n)))
    }

    /// Does `(X₁, X₂, X₃)` decompose `x_r`?
    pub fn is_decomposition(&self, xs: &[F2mElement; 3]) -> bool {
        let irr = self.irr();
        let (e1, e2, e3) = elementary_symmetric_3(&xs[0], &xs[1], &xs[2], &irr);
        symmetrised_s4_eval(&e1, &e2, &e3, &self.x_r(), &irr).is_zero()
    }

    /// Decide this instance by exhaustive search over sorted triples in
    /// the factor base.  Sorted triples are complete because the
    /// symmetrised `f₃` is symmetric in `X₁, X₂, X₃`.
    pub fn decide_exhaustively(&self) -> Option<[F2mElement; 3]> {
        let irr = self.irr();
        let x_r = self.x_r();
        let span = 1u32 << self.l;
        let elt = |v: u32| {
            let bits: Vec<u32> = (0..self.l).filter(|j| (v >> j) & 1 == 1).collect();
            F2mElement::from_bit_positions(&bits, self.n)
        };
        for a in 0..span {
            let xa = elt(a);
            for b in a..span {
                let xb = elt(b);
                for c in b..span {
                    let xc = elt(c);
                    let (e1, e2, e3) = elementary_symmetric_3(&xa, &xb, &xc, &irr);
                    if symmetrised_s4_eval(&e1, &e2, &e3, &x_r, &irr).is_zero() {
                        return Some([xa, xb, xc]);
                    }
                }
            }
        }
        None
    }
}

