#[cfg(test)]
mod tests {
    use super::*;

    /// The corpus is what upstream ships: sixty instances, evenly split
    /// across the three families and between the two labels.
    #[test]
    fn corpus_shape_is_as_shipped() {
        assert_eq!(CORPUS.len(), 60);
        assert_eq!(CORPUS.iter().filter(|c| c.truly_sat).count(), 31);
        for fam in ["n15l5", "n17l6", "n19l6"] {
            let fam_rows: Vec<_> = CORPUS.iter().filter(|c| c.name.starts_with(fam)).collect();
            assert_eq!(fam_rows.len(), 20, "{fam}");
            assert_eq!(
                fam_rows.iter().filter(|c| c.labelled_sat).count(),
                10,
                "{fam}"
            );
        }
        assert!(CORPUS.iter().all(|c| c.planted.is_some() == c.labelled_sat));
    }

    /// **Cross-implementation check.**  Every decomposition upstream
    /// planted must satisfy our symmetrised `S₄`.  Two independent
    /// implementations, one shared answer.
    #[test]
    fn corpus_planted_solutions_are_decompositions() {
        for inst in CORPUS.iter().filter(|c| c.labelled_sat) {
            let xs = inst
                .planted_elements()
                .expect("an -S instance has a planted solution");
            assert!(
                inst.is_decomposition(&xs),
                "{}: upstream's planted solution does not satisfy our S₄",
                inst.name
            );
        }
    }

    /// **The audit, re-derived in Rust.**  Decide every instance by
    /// exhaustive search and confirm `truly_sat` — including the one
    /// instance whose filename is wrong.
    ///
    /// Runs `≈ 2ᶫ³/6` field evaluations per instance; a couple of
    /// minutes in release, so it is not part of the default suite.
    #[test]
    #[ignore = "exhaustive over the whole corpus; run with --ignored"]
    fn corpus_labels_match_exhaustive_search() {
        let mut surprises = Vec::new();
        for inst in CORPUS {
            let found = inst.decide_exhaustively();
            assert_eq!(
                found.is_some(),
                inst.truly_sat,
                "{}: exhaustive search disagrees with the recorded truth",
                inst.name
            );
            if let Some(xs) = &found {
                assert!(inst.is_decomposition(xs), "{}: bad witness", inst.name);
            }
            if found.is_some() != inst.labelled_sat {
                surprises.push(inst.name);
            }
        }
        assert_eq!(
            surprises,
            vec!["n19l6-19-U"],
            "exactly one shipped instance should be mislabelled"
        );
    }

    /// The mislabelled instance, called out on its own so a failure
    /// here is unmistakable.  Cheap: we assert a specific witness
    /// rather than searching.
    #[test]
    fn mislabelled_instance_is_actually_satisfiable() {
        let inst = CORPUS
            .iter()
            .find(|c| c.name == "n19l6-19-U")
            .expect("corpus contains n19l6-19-U");
        assert!(!inst.labelled_sat, "upstream labels it UNSAT");
        assert!(inst.truly_sat, "but it is satisfiable");

        // X₁ = z⁴ + z², X₂ = z⁵ + z, X₃ = z⁵ + z³ + 1.
        let xs = [
            F2mElement::from_bit_positions(&[2, 4], inst.n),
            F2mElement::from_bit_positions(&[1, 5], inst.n),
            F2mElement::from_bit_positions(&[0, 3, 5], inst.n),
        ];
        assert!(
            inst.is_decomposition(&xs),
            "the witness must decompose the target"
        );
        for x in &xs {
            assert!(
                x.degree().is_none_or(|d| d < inst.l),
                "the witness must lie in the factor base"
            );
        }
    }

    /// **End-to-end through the SAT pipeline** on a satisfiable
    /// instance from the smaller family: encode, solve, decode, verify.
    ///
    /// Only the SAT direction is asserted.  Refuting a `-U` instance
    /// means exhausting the search space, and this solver cannot yet do
    /// that in reasonable time for any corpus family — see
    /// `research/notes/index-calculus/RESEARCH_SAT_SEMAEV.md`.  Nothing breaks symmetry, so every
    /// solution is also found in all `3!` orderings, and the Gauss-
    /// Jordan pass is rebuilt from scratch at each fixpoint.
    #[test]
    fn corpus_round_trips_through_the_solver() {
        use crate::cryptanalysis::sat::SolveResult;
        use crate::cryptanalysis::semaev_sat::{encode_semaev_s4, XorEncoding};

        let name = "n15l5-1-S";
        let inst = CORPUS.iter().find(|c| c.name == name).unwrap();
        assert!(inst.truly_sat);
        let mut enc = encode_semaev_s4(
            inst.n,
            inst.l,
            &inst.irr(),
            &inst.b(),
            &inst.x_r(),
            XorEncoding::Native,
        );
        enc.solver.conflict_budget = 20_000_000;
        assert_eq!(enc.solver.solve(), SolveResult::Sat, "{name}");
        assert!(
            inst.is_decomposition(&enc.decode()),
            "{name}: decoded triple must decompose the target"
        );
    }
}
